window.MNLCP_DATA["monitoring"] = {"_source": "MNLCP (DOFAW, 2026-09-29) Ch 8 a-f, pp. 101-114, plan text lines 4001-4575; Appendix 9 pp. A9-1 to A9-10, lines 7779-8152. cycle_steps are a site synthesis of the plan's three adaptive-management components (lines 4022-4029), the five plan-development steps (Ch 8d) and Ch 8e; the plan has no drawn adaptive management cycle (Figure 29 is a monitoring-project/data-management cycle from Sutter et al. 2015).", "cycle_steps": [{"step": 1, "title": "Set goals and objectives", "description": "Define the management goal (desired outcome and time frame) and a monitoring objective: species or ecosystem, location, attributes, method and time frame. The MNLCP already supplies the priority species or ecosystem, its location and its planning-unit population targets.", "src": "plan pp.105-106, lines 4223-4255"}, {"step": 2, "title": "Design the monitoring", "description": "Select attributes to measure, decide how much monitoring effort is warranted, choose a design (complete census, index sample or probability-based sampling), and write a monitoring protocol.", "src": "plan pp.106-110, lines 4257-4436"}, {"step": 3, "title": "Act and monitor", "description": "Carry out management actions and collect monitoring data with repeatable methods at the same locations over time.", "src": "plan p.101, line 4026; pp.103-104, lines 4142-4151"}, {"step": 4, "title": "Manage and analyze data", "description": "Verify, validate and certify data; describe it with metadata; keep it in an accessible database; and analyze it as planned.", "src": "plan pp.110-111, lines 4441-4476"}, {"step": 5, "title": "Evaluate", "description": "Hold structured, impartial reviews of the results to judge whether actions are working: annually for effectiveness, every five to ten years for recovery status.", "src": "plan p.112, lines 4485-4497"}, {"step": 6, "title": "Communicate", "description": "Give managers and decision-makers clear recommendations backed by data, and share progress with funders, partners and the public through an annual accomplishment report and a status dashboard.", "src": "plan p.112, lines 4499-4521"}, {"step": 7, "title": "Decide and adapt", "description": "Decide whether current actions are sufficient or whether the location, type or intensity of management should change, then begin the next cycle.", "src": "plan p.103, lines 4117-4120"}], "objective_types": [{"name": "Implementation monitoring", "question": "Was the planned management action carried out, and how?", "example": "Verifying that a planned action was completed and documenting where, when, how and by whom it was implemented.", "in_core_program": true, "src": "plan p.104, lines 4178-4181"}, {"name": "Effectiveness monitoring", "question": "Did the action improve ecological conditions for the population or ecosystem?", "example": "Reduced threats, more individuals, higher survival and reproduction, healthier individuals, or a restored native understory.", "in_core_program": true, "src": "plan p.104, lines 4183-4189"}, {"name": "Outcome monitoring", "question": "Is a suite of management actions preventing extinction and advancing recovery of a species or ecosystem?", "example": "Combining data across all targeted populations to track establishment of new plants, increases in distribution and range, production of fledglings, and recruitment of key ecosystem species.", "in_core_program": true, "src": "plan p.105, lines 4191-4203"}, {"name": "Impact monitoring", "question": "Is the program as a whole progressing toward recovery and restoration?", "example": "A program-wide assessment of progress toward preventing extinction, advancing recovery and restoring ecosystems, often summarized in a well-designed dashboard.", "in_core_program": true, "src": "plan p.105, lines 4205-4209"}, {"name": "Validation monitoring", "question": "Which management methods are most effective and efficient, and why?", "example": "Comparing management methods and exploring the causes behind management responses; used where there is a specific need to better understand an action.", "in_core_program": false, "src": "plan p.105, lines 4211-4216"}], "terms": [{"term": "Monitoring", "definition": "Acquiring information through repeated measurements over time and comparable data from multiple samples, to detect change, interpret results and improve management decisions.", "src": "plan p.103, lines 4133-4136"}, {"term": "Evaluation", "definition": "The systematic, objective assessment of monitoring data: whether the design meets its objectives, whether implementation was effective and efficient, and whether results are valid and ecologically sound. Required before monitoring data can inform decisions.", "src": "plan p.104, lines 4156-4160"}, {"term": "Data management", "definition": "The systematic, comprehensive and consistent handling of monitoring data to ensure its quality, accuracy and consistency and keep it in an accessible database for future analysis.", "src": "plan p.104, lines 4162-4170"}, {"term": "Adaptive management", "definition": "A structured, sequential learning process that combines monitoring, evaluation and data management to increase knowledge, reduce uncertainty and lead iteratively to more effective restoration, conservation and recovery outcomes.", "src": "plan p.104, lines 4172-4174; p.101, lines 4022-4026"}, {"term": "Management goal", "definition": "The desired outcome of management over a specific time frame: the actions to be taken and the desired impact, either a direction of change or a quantitative threshold.", "src": "plan pp.105-106, lines 4229-4236"}, {"term": "Monitoring objective", "definition": "A statement with five components: the species or ecosystem, the location, the attributes to be measured, the data collection method, and the time frame for management and monitoring.", "src": "plan p.106, lines 4238-4240"}, {"term": "Attribute", "definition": "A characteristic measured to assess management effectiveness and change in a population or ecosystem; also called an indicator, metric or parameter.", "src": "plan p.106, lines 4259-4260"}, {"term": "Detectability", "definition": "How reliably a target species or ecosystem is detected when present; affected by rarity, crypsis, low density or setting. In some cases fewer than 70 percent of individuals present are detected.", "src": "plan p.106, lines 4242-4250"}, {"term": "Covariates", "definition": "Measurements that are not the primary focus of monitoring but influence the primary attribute, such as invasive cover, soil disturbance, rainfall or temperature.", "src": "plan p.106, lines 4273-4276; App 9 p.A9-2, lines 7831-7839"}, {"term": "Complete census", "definition": "Counting all individuals (or population units such as burrows), or fully measuring an ecosystem, within a defined area.", "src": "plan p.108, lines 4326-4333"}, {"term": "Index sample", "definition": "One or more nonrandomly placed sample areas used to track trends; cannot be used to statistically estimate the whole population.", "src": "plan p.108, lines 4347-4353"}, {"term": "Probability-based sampling", "definition": "Drawing a representative subset of a population or ecosystem and using statistics to estimate the whole.", "src": "plan p.108, lines 4354-4358"}, {"term": "Target population", "definition": "All individuals in a population, or all features of an ecosystem, about which a sample is designed to draw conclusions.", "src": "App 9 p.A9-1, lines 7797-7798"}, {"term": "Sampling error", "definition": "The difference between a sample statistic and the true population value caused by measuring only part of the population; a natural feature of sampling, not a mistake.", "src": "App 9 p.A9-2, lines 7819-7824"}, {"term": "Precision", "definition": "How close repeated measurements are to one another; distinct from accuracy, which is closeness to the true value.", "src": "App 9 p.A9-2, lines 7825-7828"}, {"term": "Power", "definition": "The ability of a sampling design to detect a true change in the target population. (Plan wording differs; see notes.)", "src": "App 9 p.A9-2, lines 7829-7830"}, {"term": "Power analysis", "definition": "Calculating the minimum sample size needed to detect a change of a given magnitude.", "src": "plan p.111, lines 4467-4469"}, {"term": "Monitoring protocol", "definition": "A living document, ideally online and updated annually, giving written guidance on how monitoring is implemented so it is consistent over time, across locations and among staff.", "src": "plan p.110, lines 4415-4421"}, {"term": "Verification, validation, certification", "definition": "The three data quality steps: verification checks completeness, validation checks that data make scientific sense, and certification confirms data are ready for use and sharing.", "src": "plan p.111, lines 4459-4461; App 9 p.A9-9, lines 8118-8125"}]};
